/* Lot 93: pow, sqrt, hypot, log and exp simplified (generated by scripts/lot93_mathgen.py; expectations from lot93_mathmodel.py). */

#include "../../framework/unity.h"
#include <string.h>
#include <stdio.h>
#include "wf_cssprop.h"

static char g_o[64], g_r[96];

static const char *ev(const char *v) {
    int t = -1, r = wf_cssprop_math_eval(v, &t, g_o, (int)sizeof(g_o));
    if (r < 0) return t == 0 && !g_o[0] ? "BAD" : "BAD BUT SET";
    if (r == 0) snprintf(g_r, sizeof(g_r), "T%d %s", t, g_o[0] ? "WRITTEN" : "KEEP");
    else snprintf(g_r, sizeof(g_r), "T%d %s", t, g_o);
    return g_r;
}

static void test_l93_powlog_0(void) {
    TEST_ASSERT_EQUAL_STRING("T5 9.9", ev("sqrt(  98.01)"));
    TEST_ASSERT_EQUAL_STRING("T5 2.9575", ev("Log(  632.39, 8.853 )"));
    TEST_ASSERT_EQUAL_STRING("T5 1", ev("pOW(7,0)"));
    TEST_ASSERT_EQUAL_STRING("T5 KEEP", ev("pow(-4.0,2.3\t)"));
    TEST_ASSERT_EQUAL_STRING("T5 KEEP", ev("pOW(  -33.70853,  9 )"));
    TEST_ASSERT_EQUAL_STRING("T5 0.0009", ev("exp(-7\t)"));
    TEST_ASSERT_EQUAL_STRING("T5 0", ev("ExP( -10)"));
    TEST_ASSERT_EQUAL_STRING("T5 KEEP", ev("pow(-4.186,1.6  )"));
}

